    timeDiff: function(startTm, endTm) {
            var endH = endTm.substr(0,2);
            var endM = endTm.substr(2,2);
            var startH = startTm.substr(0,2);
            var startM = startTm.substr(2,2);
            if(endM < startM){
              endM = Number(endM)+60;
              endH -= 1;
            }
            return (endH-startH) + (((endM-startM))/60*10).toFixed(1)/10;
    },

    dateToTimeTable: function(date, sperator) {
        var me = this,
            vm = me.getViewModel();
        var refs = me.getReferences();

        var year = date.getFullYear();
        var month = date.getMonth()+1;
        month = month < 10 ? "0" + month: month;
        var day = date.getDate();
        day = day < 10 ? "0" + day: day;

        return year +sperator + month +sperator +  day;
    },

