    /* 결재 버튼 클릭 이벤트 */
    onBtnAplyTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            docNm = vm.get('docNm'),
            approvalLineGrid = refs.approvalLineGrid,
            aprHistId = null;

        if(vm.clicked == 'rept'){
            me.updateReptAndCheck(true);
        } else {
            var aplOvtStrdt = DateUtils.getDate(refs.aplOvtStrdt.getValue());
            var aplOvtEdt = DateUtils.getDate(refs.aplOvtEdt.getValue());
            var aplOvtStrtm= DateUtils.encodeDate(refs.aplOvtStrtm.getValue()).substr(11,8).replace(/:/g,'');
            var aplOvtEdtm=DateUtils.encodeDate(refs.aplOvtEdtm.getValue()).substr(11,8).replace(/:/g,'');
            var timediff = me.timeDiff(aplOvtStrtm,aplOvtEdtm);

            if(refs.aplDvcd.getValue() == '01'){
                if(aplOvtEdtm.length>6){
                    msg = "연장근무 일자를 정확히 입력해주십시오.";
                    Ext.Msg.alert("유효성 검증", msg);
                    return;
                }

                //     if(Number(refs.maxOvttmMnth.getValue())<Number(refs.ovttmMnth.getValue())+timediff){
                //         msg = "월 최대 연장근무 신청시간을 초과하였습니다.";
                //         Ext.Msg.alert("유효성 검증", msg);
                //         return;
                //     }

                if(timediff > refs.maxOvttmDay.getValue() || timediff < 0){
                    msg = "연장근무 신청시간을 확인해주십시오.";
                    Ext.Msg.alert("유효성 검증", msg);
                    return;
                }

                if(timediff < 0.5){
                    msg = "연장근무는 30분 이상 신청 가능합니다.";
                    Ext.Msg.alert("유효성 검증", msg);
                    return;
                }

            }

            me.updateAplyAndCheck(true);

        }

    },

    /* 보고 버튼 클릭 이벤트 */
    onBtnReptTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var params = {};
        params.wrkDt = me.dateToTimeTable(refs.aplOvtDt.getValue(), "");
        params.wrkStrtm = DateUtils.encodeDate(refs.aplOvtStrtm.getValue()).substr(11,8).replace(/:/g,'');
        params.hrHrpmEmpId = SecurityUtils.getPrincipal().hrHrpmEmpId;
        params.aplDvcd = refs.aplDvcd.getValue();
        params.sttDate = me.dateToTimeTable(new Date(), "");
        params.reptType = 'OVT';
        params.aplDt = Ext.Date.format(new Date(), 'Ymd');


        Ext.Ajax.request({
            headers : {
                serviceId : 'HwmOvtSvc.findOneHwmOvtRept',
                viewId : 'HwmOvtAply02M'
            },
            scope : me,
            jsonData : params,
            success : function(response) {
                var ob = JSON.parse(response.responseText);
                var wrkDay = ob.wrkDay;
                var ovtHodMap = ob.ovtHodMap;
                var resErrMsg = ob.errMsg;

                var aplOvtDt = DateUtils.getDate(refs.aplOvtDt.getValue());
                var aplOvtStrtm = refs.aplOvtStrtm.getValue();
                //TODO : datetimeFormat convert  변환하는 함수 공통으로 만들기
                var timeObj = refs.aplOvtStrtm.getValue();
                var hh = timeObj.getHours()+"";
                var mi = timeObj.getMinutes()+"";
                hh = (hh.length == 1 ? '0' : "") + hh;
                mi = (mi.length == 1 ? '0' : "") + mi;

                aplOvtStrtm = hh + "" + mi;

                if(wrkDay && wrkDay.wrkEdt){
                    if(aplOvtDt == wrkDay.wrkDt && (new Date(wrkDay.wrkStrdt).getTime() >= new Date(wrkDay.wrkEdt).getTime()) && (new Date(aplOvtStrtm).getTime() >= new Date(wrkDay.wrkEdtm.replace(':','')).getTime())){
                        //유효성 체크 추가. update by jihyun
                        Ext.Msg.alert("안내", "실 퇴근일시가 연장근무 시작일시보다 이전이면 <br> 연장근무 보고를 할 수 없습니다.");
                        return;
                    }

                    me.setReptComponent(e);
                    refs.wrkStrdt.setValue(wrkDay.wrkStrdt);
                    refs.wrkEdt.setValue(wrkDay.wrkEdt);
                    refs.wrkStrtm.setValue(wrkDay.wrkStrtm);
                    refs.wrkEdtm.setValue(wrkDay.wrkEdtm);
                } else if(e !== null){
                    msg = "해당일자에 출퇴근 정보가 존재하지 않습니다.";
                    Ext.Msg.alert("유효성 검증", msg);
                    return;
                }


                if(e !== null && resErrMsg !== undefined){
                    Ext.Msg.alert("유효성 검증", resErrMsg);
                    return;
                }

                refs.totOvtHodMonthDds.setValue(ovtHodMap.monthDds);
                refs.totOvtHodMonthHr.setValue(ovtHodMap.monthHr);
                refs.totOvtHodWeekDds.setValue(ovtHodMap.weekDds);
                refs.totOvtHodWeekHr.setValue(ovtHodMap.weekHr);

                //         refs.ovtHodMnth.setValue(ovtHodMap.monthDds + "일 (" + ovtHodMap.monthHr + "시간)");
                //         refs.ovtHodWeek.setValue(ovtHodMap.weekDds + "일 (" + ovtHodMap.weekHr + "시간)");

                //         if(wrkMnth){
                //             refs.totOvtHr.setHtml(wrkMnth.totOvtHr);
                //             refs.totHodHr.setHtml(wrkMnth.totHodHr);
                //         }
            }
        });

    },

