    cancel: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var msg = "※<b>유의사항<br>";
        if(vm.clicked == 'rept'){
            // 여비정산서 신청여부
            if (vm.get('existBgBtrYn') == 'Y') {
                Ext.Msg.alert("안내", "해당 건에 대해서 예산_여비정산서신청이 '진행/완료'된 신청서가 있습니다.<br> 신청 회수/취소 후 다시 신청바랍니다. ");
                return false;
            }

            msg = msg + "연장근무보고 취소시, 연장근무취소는<br>따로 신청취소를 해야되며,<br>보고취소는 결재없이 바로 취소됩니다.<br><br>";
        } else {
            msg = msg + "신청취소시 결재없이 바로 취소됩니다.</b><br><br>";
        }
        msg = msg + "정말로 취소하시겠습니까?<br>";

        Ext.Msg.confirm('알림', msg, function(btn) {
            if (btn == 'yes') {
                //신청	01
                //취소신청	02
                refs.aplDvcdNm.setHidden(false);
                refs.aplDvcdNm.setValue("취소신청");
                refs.aplDvcd.setValue("02");

                refs.apLn.setHidden(true);
                refs.ap.setHidden(false);
                refs.reAp.setHidden(true);
                refs.cancel.setHidden(true);
                refs.rept.setHidden(true);

                refs.ap.setText("취소완료");

                if(vm.clicked == 'rept'){
                    vm.set('docCd', 'HwmOvtRept72');
                    vm.set('docNm', '연장근무보고 취소신청서');
                } else {
                    vm.set('docCd', 'HwmOvtAply72');
                    vm.set('docNm', '연장근무 취소신청서');

                    //     refs.aplCntn.setDisabled(false);
                    //     refs.aplCntn.setValue("취소 신청하겠습니다.");
                }

                //             ApprovalBoxSvc.setup({
                //                 command   : Constants.sanction.DRAFT,
                //                 viewModel : vm,
                //                 edocCd    : vm.get('docCd'),
                //                 scope     : me
                //             });
            } else {
                return false;
            }
        });

    }

